package com.aetherforge.service;
import com.aetherforge.repo.OperationalRepository;import org.springframework.stereotype.Service;import java.util.*;
@Service public class AutonomousService {private final OperationalRepository ops;public AutonomousService(OperationalRepository o){ops=o;}public Map<String,Object> decide(String id,String decision,String actor,String role){if(!Set.of("ENGINEER","ADMIN").contains(role))throw new SecurityException("Engineer approval required");var a=ops.action(id);if(decision.equals("APPROVE")){ops.setAction(id,"APPROVED",actor);ops.audit(actor,role,"AUTONOMOUS_APPROVAL","AUTONOMOUS_ACTION",id,"APPROVED",UUID.randomUUID().toString());return ops.action(id);}if(decision.equals("REJECT")){ops.setAction(id,"CANCELLED",actor);ops.audit(actor,role,"AUTONOMOUS_REJECTION","AUTONOMOUS_ACTION",id,"REJECTED",UUID.randomUUID().toString());return ops.action(id);}return a;}public Map<String,Object> execute(String id,String actor,String role){if(!Set.of("ENGINEER","ADMIN").contains(role))throw new SecurityException("Engineer approval required");var a=ops.action(id);if(!"APPROVED".equals(a.get("state")))throw new IllegalStateException("Action must be APPROVED first");ops.setAction(id,"EXECUTING",actor);if(a.get("machine_code")!=null){String mid=String.valueOf(a.get("machine_id"));ops.createMaintenance(mid,"HIGH",actor);}ops.setAction(id,"COMPLETED",actor);if(a.get("machine_id")!=null)ops.recoverMachine(String.valueOf(a.get("machine_id")));ops.setAction(id,"VERIFIED",actor);ops.audit(actor,role,"AUTONOMOUS_EXECUTION","AUTONOMOUS_ACTION",id,"VERIFIED",UUID.randomUUID().toString());return ops.action(id);}}
